/**
 * server.mjs — خادم تطبيق عروض الأسعار (واجهة عربية RTL)
 * يعتمد فقط على وحدات Node المدمجة: http و fs و path (بلا أي اعتماديات خارجية).
 * يستمع على المنفذ 3000.
 *
 * API:
 *   POST /api/quote
 *   الجسم (JSON): { items: [{ sku, unitPriceCents, quantity }], discountPercent, shippingCents }
 *   النجاح 200: { subtotalCents, discountCents, shippingCents, totalCents }
 *   أي إدخال مخالف أو JSON معطوب: 400 { error: "invalid" }
 */

import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const PORT = 3000;

// جذر الملفات الثابتة = المجلد الذي يقع فيه ملف الخادم نفسه
const ROOT = path.resolve(process.argv[1] ? path.dirname(process.argv[1]) : ".");

const MAX_BODY_BYTES = 1_000_000; // حد أمان لحجم جسم الطلب
const MAX_ITEMS = 100; // الأصناف من 1 إلى 100
const MAX_SUBTOTAL_CENTS = 1_000_000_000; // سقف مجموع الأسعار قبل الخصم

/* ---------------- أدوات مساعدة ---------------- */

function sendJson(res, status, payload, extraHeaders = {}) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
    "Cache-Control": "no-store",
    ...extraHeaders,
  });
  res.end(body);
}

function sendInvalid(res) {
  sendJson(res, 400, { error: "invalid" });
}

function sendNotFound(res) {
  sendJson(res, 404, { error: "not found" });
}

// تحقق صارم: عدد صحيح آمن ضمن مجال محدد.
// لا يوجد أي تحويل للنصوص أو null أو المنطقيات إلى أرقام.
function isIntIn(value, min, max) {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value >= min &&
    value <= max
  );
}

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/* ---------------- منطق التسعير ---------------- */

// يُرجع كائن النتيجة عند صحة المدخلات، أو null عند أي مخالفة.
function computeQuote(body) {
  if (!isPlainObject(body)) return null;

  const items = body.items;
  if (!Array.isArray(items) || items.length < 1 || items.length > MAX_ITEMS) {
    return null;
  }

  const seenSkus = new Set();
  let subtotalCents = 0;

  for (const item of items) {
    if (!isPlainObject(item)) return null;

    // sku: نص غير فارغ بعد trim وغير مكرر ضمن الطلب
    if (typeof item.sku !== "string") return null;
    const trimmedSku = item.sku.trim();
    if (trimmedSku.length === 0) return null;
    if (seenSkus.has(trimmedSku)) return null;
    seenSkus.add(trimmedSku);

    // unitPriceCents: عدد صحيح آمن من 0 إلى 10000000
    if (!isIntIn(item.unitPriceCents, 0, 10_000_000)) return null;
    // quantity: عدد صحيح من 1 إلى 10000
    if (!isIntIn(item.quantity, 1, 10_000)) return null;

    subtotalCents += item.unitPriceCents * item.quantity;
    if (subtotalCents > MAX_SUBTOTAL_CENTS) return null; // سقف ما قبل الخصم
  }

  // discountPercent: عدد صحيح من 0 إلى 100
  if (!isIntIn(body.discountPercent, 0, 100)) return null;
  // shippingCents: عدد صحيح من 0 إلى 1000000
  if (!isIntIn(body.shippingCents, 0, 1_000_000)) return null;

  // الخصم يُحسب من المجموع الفرعي فقط (الشحن لا يدخل في الخصم).
  // discountCents = تقريب (subtotal × percent ÷ 100) إلى أقرب سنت والنصف للأعلى،
  // بصيغة أعداد صحيحة مكافئة تمامًا لـ Math.floor(x + 0.5) حيث x = n / 100.
  const discountCents = Math.floor((subtotalCents * body.discountPercent + 50) / 100);
  const totalCents = subtotalCents - discountCents + body.shippingCents;

  return {
    subtotalCents,
    discountCents,
    shippingCents: body.shippingCents,
    totalCents,
  };
}

/* ---------------- قراءة جسم الطلب ---------------- */

// يُرجع نص الجسم، أو null عند تجاوز الحد أو خطأ في القراءة.
function readBody(req) {
  return new Promise((resolve) => {
    const chunks = [];
    let size = 0;
    let overflow = false;

    req.on("data", (chunk) => {
      if (overflow) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        overflow = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(overflow ? null : Buffer.concat(chunks).toString("utf8")));
    req.on("error", () => resolve(null));
  });
}

/* ---------------- الملفات الثابتة ---------------- */

const MIME_TYPES = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
};

function serveStatic(res, pathname) {
  let decoded;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    sendNotFound(res);
    return;
  }

  const rel = decoded === "/" || decoded === "" ? "index.html" : decoded.replace(/^\/+/, "");
  const filePath = path.normalize(path.join(ROOT, rel));

  // منع الخروج عن جذر الملفات (path traversal)
  if (filePath !== ROOT && !filePath.startsWith(ROOT + path.sep)) {
    sendNotFound(res);
    return;
  }

  fs.stat(filePath, (statErr, stats) => {
    if (statErr || !stats.isFile()) {
      sendNotFound(res);
      return;
    }
    fs.readFile(filePath, (readErr, data) => {
      if (readErr) {
        sendNotFound(res);
        return;
      }
      res.writeHead(200, {
        "Content-Type":
          MIME_TYPES[path.extname(filePath).toLowerCase()] || "application/octet-stream",
        "Content-Length": data.length,
        "Cache-Control": "no-store",
      });
      res.end(data);
    });
  });
}

/* ---------------- الخادم ---------------- */

async function handleRequest(req, res) {
  res.on("error", () => {}); // تجاهل أخطاء الكتابة بعد انقطاع العميل

  let pathname;
  try {
    pathname = new URL(req.url || "/", "http://localhost").pathname;
  } catch {
    sendInvalid(res);
    return;
  }

  if (pathname === "/api/quote") {
    if (req.method !== "POST") {
      sendJson(res, 405, { error: "invalid" }, { Allow: "POST" });
      return;
    }

    const raw = await readBody(req);
    if (raw === null) {
      sendInvalid(res); // جسم مفقود أو أكبر من الحد المسموح
      return;
    }

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch {
      sendInvalid(res); // JSON معطوب
      return;
    }

    const result = computeQuote(parsed);
    if (result === null) {
      sendInvalid(res); // مدخلات مخالفة
      return;
    }

    sendJson(res, 200, result);
    return;
  }

  if (req.method === "GET" || req.method === "HEAD") {
    serveStatic(res, pathname);
    return;
  }

  sendNotFound(res);
}

const server = http.createServer((req, res) => {
  handleRequest(req, res).catch((err) => {
    console.error("[quote-server] خطأ غير متوقع:", err);
    if (!res.headersSent) {
      sendJson(res, 500, { error: "internal" });
    } else {
      res.destroy();
    }
  });
});

server.on("clientError", (err, socket) => {
  if (socket.writable) {
    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n");
  }
});

server.listen(PORT, () => {
  console.log(`[quote-server] يعمل على المنفذ ${PORT} — جذر الملفات: ${ROOT}`);
});

