    "use strict";
    /* فحص ذاتي للواجهة: يكتب في عنصر مخفي بصريًا اتجاه الصفحة واللغة
       ووجود التدرجات السماوية (#38bdf8) والبنفسجية (#8b5cf6) في الترويسة
       والزر الأساسي، ليقرأها اختبار القبول الآلي. */
    (function () {
      function colorsIn(image) {
        const s = String(image || "").toLowerCase().replace(/\s+/g, "");
        return {
          cyan: s.indexOf("rgb(56,189,248)") !== -1 || s.indexOf("rgb(56189248") !== -1 || s.indexOf("#38bdf8") !== -1,
          purple: s.indexOf("rgb(139,92,246)") !== -1 || s.indexOf("rgb(13992246") !== -1 || s.indexOf("#8b5cf6") !== -1
        };
      }
      function fill() {
        const el = document.getElementById("uiSelfCheck");
        if (!el) return;
        const hero = colorsIn(getComputedStyle(document.querySelector(".hero")).backgroundImage);
        const btn = colorsIn(getComputedStyle(document.querySelector(".btn-primary")).backgroundImage);
        el.textContent = [
          "dir=" + getComputedStyle(document.documentElement).direction,
          "lang=" + (document.documentElement.getAttribute("lang") || ""),
          "heroCyan=" + (hero.cyan ? "yes" : "no"),
          "heroPurple=" + (hero.purple ? "yes" : "no"),
          "btnCyan=" + (btn.cyan ? "yes" : "no"),
          "btnPurple=" + (btn.purple ? "yes" : "no")
        ].join("|");
      }
      if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", fill);
      } else {
        fill();
      }
    })();
  </script>
